function d2ab(dataURI){
  if(typeof dataURI!=='string'){try{return new Uint8Array(dataURI).buffer}catch(e){throw new Error('d2ab: unsupported data type')}}
  var s=dataURI.trim()
  // 1) 鏍囧噯 Data URL
  if(s.indexOf('data:')===0){
    var commaIdx=s.indexOf(','),head=s.substring(0,commaIdx),body=s.substring(commaIdx+1)
    if(head.indexOf(';base64')>=0){
      // base64 鍒嗘敮
      try{var raw=atob(body),arr=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)arr[i]=raw.charCodeAt(i);return arr.buffer}
      catch(e){
        // 鏍囪浜?;base64 浣嗘暟鎹疄闄呮槸 URL 缂栫爜鏂囨湰鐨勫吋瀹规儏鍐?
        try{return new TextEncoder().encode(decodeURIComponent(body)).buffer}
        catch(e2){throw e}
      }
    }else{
      // URL 缂栫爜鏂囨湰鍒嗘敮
      return new TextEncoder().encode(decodeURIComponent(body)).buffer
    }
  }
  // 2) 绾?base64 瀛楃涓诧紙瀛橀噺鍏煎锛氭棤 data: 鍓嶇紑鐨勫師濮?base64锛?
  if(/^[A-Za-z0-9+/=]+$/.test(s)){
    try{var raw2=atob(s),arr2=new Uint8Array(raw2.length);for(var j=0;j<raw2.length;j++)arr2[j]=raw2.charCodeAt(j);return arr2.buffer}
    catch(e){throw e}
  }
  // 3) 绾枃鏈厹搴?
  return new TextEncoder().encode(s).buffer
}

